.loot-container {
  max-height: 400px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(100,160,255,.5) transparent;
}
.loot-container::-webkit-scrollbar {
  width: 6px;
}
.loot-container::-webkit-scrollbar-thumb {
  background-color: rgba(100,160,255,.5);
  border-radius: 3px;
}
.loot-toggles {
  display: flex;
  gap: 4px;
  padding: 4px 6px;
}
.loot-toggle {
  padding: 2px 8px;
  border-radius: 3px;
  cursor: pointer;
  font-size: 12px;
  background: color-mix(in srgb, currentColor 8%, transparent);
  opacity: 0.5;
}
.loot-toggle:hover {
  opacity: 0.7;
}
.loot-toggle.active {
  background: rgba(100,160,255,.25);
  opacity: 1;
}
table {
  border-collapse: collapse;
  margin: 0px 6px;
  width: calc(100% - 12px);
}
td, th {
  padding: 2px 5px;
  text-align: end;
}
td:first-child, th:first-child {
  text-align: start;
}
td:nth-child(even), th:nth-child(even) {
  background-color: color-mix(in srgb, currentColor 15%, transparent);
}
.total-row td {
  border-top: 1px solid color-mix(in srgb, currentColor 20%, transparent);
}
.tree {
  padding: 0 6px;
}
.kill-group {
  margin-bottom: 4px;
}
.kill-header {
  font-weight: bold;
  padding: 2px 0;
  border-bottom: 1px solid color-mix(in srgb, currentColor 15%, transparent);
}
.kill-item {
  padding: 1px 0 1px 12px;
  font-size: 12px;
  opacity: 0.75;
}
.tree .total-row {
  padding: 4px 0;
  border-top: 1px solid color-mix(in srgb, currentColor 20%, transparent);
}
